import '@fontsource/archivo-black/latin-400.css';
import '@fontsource/ibm-plex-sans/latin-400.css';
import '@fontsource/ibm-plex-sans/latin-500.css';
import '@fontsource/ibm-plex-sans/latin-600.css';
import './styles.css';
import { icon, focusMain } from './lib/dom.js';
import { isMockMode } from './lib/api.js';

const app = document.querySelector('#app');
let cleanup = null;

function shell(content, { section = 'public' } = {}) {
  const operational = section === 'admin' || section === 'scanner';
  return `
    <header class="site-header ${operational ? 'site-header--ops' : ''}">
      <a class="wordmark" href="/" data-link aria-label="Tixora events">
        <span class="wordmark__mark" aria-hidden="true">T</span><span>TIXORA</span>
      </a>
      <nav class="site-nav" aria-label="Primary navigation">
        <a href="/events" data-link ${section === 'public' ? 'aria-current="page"' : ''}>What’s on</a>
        <a href="/admin" data-link ${section === 'admin' ? 'aria-current="page"' : ''}>Box office</a>
        <a href="/check-in" data-link ${section === 'scanner' ? 'aria-current="page"' : ''}>Door</a>
      </nav>
      ${isMockMode ? '<span class="demo-flag">Demo data</span>' : ''}
      <button class="menu-button" data-menu aria-expanded="false" aria-label="Open navigation">${icon('menu')}</button>
    </header>
    ${content}
    <footer class="site-footer">
      <div><strong>TIXORA</strong><span>Tickets that get people through the door.</span></div>
      <nav aria-label="Footer"><a href="/privacy" data-link>Privacy</a><a href="/terms" data-link>Ticket terms</a><a href="/support" data-link>Support</a></nav>
      <small>Working sandbox · Times shown in WAT</small>
    </footer>`;
}

async function render() {
  cleanup?.();
  cleanup = null;
  const path = window.location.pathname.replace(/\/+$/, '') || '/';
  let view;
  try {
    if (path === '/' || path === '/events') {
      const { eventsView } = await import('./views/events.js'); view = await eventsView();
    } else if (path.startsWith('/event/')) {
      const { eventView } = await import('./views/event.js'); view = await eventView(decodeURIComponent(path.split('/')[2] || ''));
    } else if (path === '/order/status') {
      const { statusView } = await import('./views/status.js'); view = await statusView();
    } else if (path === '/admin' || path.startsWith('/admin/')) {
      const { adminView } = await import('./views/admin.js'); view = await adminView(path);
    } else if (path === '/check-in' || path.startsWith('/check-in/')) {
      const { scannerView } = await import('./views/scanner.js'); view = await scannerView(path);
    } else if (['/privacy', '/terms', '/support'].includes(path)) {
      const { legalView } = await import('./views/legal.js'); view = legalView(path);
    }
    else view = { html: `<main id="main" class="not-found" tabindex="-1"><p class="kicker">404 / WRONG TURN</p><h1>This page isn’t on the bill.</h1><p>The event may have moved or the address is incomplete.</p><a class="button button--ink" href="/events" data-link>${icon('back')} See all events</a></main>` };
  } catch (error) {
    console.error(error);
    view = { html: `<main id="main" class="not-found" tabindex="-1"><p class="kicker">SOMETHING BROKE</p><h1>We couldn’t set the page.</h1><p>${error.message || 'Please try again.'}</p><button class="button button--ink" onclick="location.reload()">Try again</button></main>` };
  }
  app.innerHTML = shell(view.html, view.meta || {});
  cleanup = view.mount?.() || null;
  wireShell();
  focusMain();
}

function wireShell() {
  const menu = document.querySelector('[data-menu]');
  const nav = document.querySelector('.site-nav');
  menu?.addEventListener('click', () => {
    const open = menu.getAttribute('aria-expanded') === 'true';
    menu.setAttribute('aria-expanded', String(!open));
    nav?.classList.toggle('site-nav--open', !open);
  });
}

export function navigate(path) {
  history.pushState({}, '', path);
  window.scrollTo({ top: 0, behavior: 'instant' });
  render();
}

document.addEventListener('click', (event) => {
  const link = event.target.closest('a[data-link]');
  if (!link || link.target || event.metaKey || event.ctrlKey || event.shiftKey) return;
  const url = new URL(link.href, location.origin);
  if (url.origin !== location.origin) return;
  event.preventDefault();
  navigate(`${url.pathname}${url.search}${url.hash}`);
});
window.addEventListener('popstate', render);
render();
