export function toast(message, tone = 'info') {
  const region = document.querySelector('#toast-region');
  if (!region) return;
  const item = document.createElement('div');
  item.className = `toast toast--${tone}`;
  item.innerHTML = `<span>${message}</span><button aria-label="Dismiss">×</button>`;
  item.querySelector('button').addEventListener('click', () => item.remove());
  region.append(item);
  setTimeout(() => item.remove(), 5000);
}

export function setTitle(value) {
  document.title = value ? `${value} — Tixora` : 'Tixora — What’s happening next';
}

export function focusMain() {
  requestAnimationFrame(() => document.querySelector('#main')?.focus({ preventScroll: true }));
}
